export function localizedKbTitle(
  locale: "tr" | "en",
  slug: string | undefined,
  fallback?: string
): string {
  if (slug && KB_TITLES[locale][slug]) return KB_TITLES[locale][slug];
  if (fallback) {
    // Cross-locale fallback: TR title in → EN title out via reverse lookup
    const other = locale === "en" ? "tr" : "en";
    for (const [s, title] of Object.entries(KB_TITLES[other])) {
      if (title === fallback) return KB_TITLES[locale][s] ?? fallback;
    }
  }
  return fallback ?? slug ?? "";
}

